1	// Soporte exclusivo de las pruebas de spec-0. Complementa factory/regresion/helpers.ts (que este spec no puede editar).
2	// Selectores tomados del código de Moodle 5.3 en entorno/.moodle-src/. Las aserciones que deciden si un criterio se
3	// cumple están en los .spec.ts; acá solo hay esperas y comprobaciones de que cada paso auxiliar terminó bien.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	import { bloquePregunta } from '../../../factory/regresion/helpers';
6	
7	export type TipoPregunta = 'multichoice' | 'truefalse' | 'essay';
8	export type Categoria = { id: string; contexto: string };
9	
10	type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };
11	
12	const configMoodle = (page: Page): Promise<ConfigMoodle> =>
13	  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);
14	
15	/** Nombre único que no contiene "Examen de regresión", para que abrirQuiz nunca tome este examen por QUIZ-REG. */
16	export const nombreUnico = (prefijo: string, proyecto: string) => `${prefijo} ${proyecto} ${Date.now()}`;
17	
18	/**
19	 * TinyMCE crea su iframe oculto y lo muestra al terminar de cargar sus módulos, lo que puede superar los 5 s por defecto
20	 * de expect con el servidor bajo carga. Es una espera de carga: la aserción sobre el editor no cambia.
21	 */
22	export const ESPERA_EDITOR = 30_000;
23	
24	/**
25	 * Espera a que terminen de inicializarse los módulos AMD de la página (misma señal que usa Behat y enviarIntento() de
26	 * helpers.ts). Sustituye a 'networkidle', que en Moodle nunca se cumple por sus peticiones periódicas.
27	 */
28	export async function esperarModulos(page: Page) {
29	  await page.waitForLoadState('load');
30	  await page.waitForFunction(() => (window as unknown as { M?: { util?: { pending_js?: unknown[] } } }).M?.util?.pending_js?.length === 0);
31	}
32	
33	export async function idCursoQA101(page: Page): Promise<number> {
34	  await page.goto('/course/view.php?name=QA101');
35	  return (await configMoodle(page)).courseId;
36	}
37	
38	// ---------------------------------------------------------------------------------------------------------
39	// Examen
40	
41	export async function abrirFormularioExamen(page: Page, curso: number) {
42	  await page.goto(`/course/modedit.php?add=quiz&course=${curso}&section=0`);
43	  await expect(page.locator('#id_introeditor_ifr')).toBeVisible({ timeout: ESPERA_EDITOR });
44	}
45	
46	/**
47	 * Deja abierto el índice del curso (solo escritorio) para capturar siempre el mismo estado. Abierto o cerrado es una
48	 * preferencia guardada por usuario (drawer-open-index, boost/layout/drawers.php:34) que sobrevive entre corridas: no es
49	 * parte de la pantalla que se protege. En móvil no aplica: drawers.js:328 lo cierra al cargar sin mirar la preferencia.
50	 */
51	export async function abrirIndiceCurso(page: Page) {
52	  const abrir = page.getByRole('button', { name: 'Open course index' });
53	  if (await abrir.isVisible()) await abrir.click();
54	  await expect(page.getByRole('button', { name: 'Close course index' })).toBeVisible();
55	}
56	
57	/** Guarda con "Save and display" y devuelve el cmid del examen creado o editado. */
58	export async function guardarExamen(page: Page): Promise<number> {
59	  await page.getByRole('button', { name: 'Save and display' }).click();
60	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
61	  return Number(new URL(page.url()).searchParams.get('id'));
62	}
63	
64	export async function crearExamen(page: Page, curso: number, nombre: string): Promise<number> {
65	  await abrirFormularioExamen(page, curso);
66	  await page.locator('#id_name').fill(nombre);
67	  return guardarExamen(page);
68	}
69	
70	export async function eliminarExamen(page: Page, cmid: number) {
71	  const { sesskey } = await configMoodle(page);
72	  await page.goto(`/course/mod.php?delete=${cmid}&sesskey=${sesskey}`);
73	  await page.getByRole('button', { name: 'Yes', exact: true }).click();
74	  await expect(page).toHaveURL(/course\/(view|section)\.php/);
75	}
76	
77	// ---------------------------------------------------------------------------------------------------------
78	// Banco de preguntas
79	
80	/** cmid del banco compartido de QA101, leído de la lista de bancos del curso. */
81	export async function cmidBanco(page: Page, curso: number): Promise<number> {
82	  await page.goto(`/question/banks.php?courseid=${curso}`);
83	  const banco = page.locator('.shared-banks .questioncount[data-cmid]').first();
84	  await expect(banco).toBeAttached();
85	  return Number(await banco.getAttribute('data-cmid'));
86	}
87	
88	export const urlCategorias = (banco: number) => `/question/bank/managecategories/category.php?cmid=${banco}`;
89	const urlBanco = (banco: number, c: Categoria) => `/question/edit.php?cmid=${banco}&cat=${c.id},${c.contexto}`;
90	
91	export const filaCategoria = (page: Page, nombre: string): Locator =>
92	  page.locator(`li.qbank_managecategories-item[data-categoryname=${JSON.stringify(nombre)}]`);
93	
94	export const filaPregunta = (page: Page, nombre: string): Locator =>
95	  page.locator('#categoryquestions tbody tr', { hasText: nombre });
96	
97	/**
98	 * Crea una categoría propia en el banco. Es necesaria porque el banco sembrado no tiene categoría por defecto
99	 * (question_bank_helper.php:660 usa skipdefaultcategory): sin esto, las preguntas caerían en Álgebra.
100	 */
101	export async function crearCategoria(page: Page, banco: number, nombre: string): Promise<Categoria> {
102	  await page.goto(urlCategorias(banco));
103	  // El botón recibe su evento cuando el componente reactivo termina de cargar el estado.
104	  await esperarModulos(page);
105	  await page.locator('#qbank_managecategories-addcategory [data-action="addeditcategory"]').click();
106	  const modal = page.locator('[data-region="modal"]').filter({ has: page.locator('input[name="name"]') });
107	  await modal.locator('input[name="name"]').fill(nombre);
108	  await modal.locator('[data-action="save"]').click();
109	  await expect(filaCategoria(page, nombre)).toHaveCount(1);
110	  await page.reload();
111	  const id = await filaCategoria(page, nombre).getAttribute('data-categoryid');
112	  const { contextid } = await configMoodle(page);
113	  return { id: String(id), contexto: String(contextid) };
114	}
115	
116	/** Escribe en un editor TinyMCE. `iframe` es el selector CSS de su iframe. */
117	export async function escribirEditor(page: Page, iframe: string, texto: string) {
118	  await expect(page.locator(iframe)).toBeVisible({ timeout: ESPERA_EDITOR });
119	  // El iframe ya es visible mientras TinyMCE sigue cargando: su "throbber" (aria-busy) tapa el editor e intercepta el
120	  // click. Se espera a que desaparezca antes de interactuar.
121	  await expect(page.locator('.tox-tinymce', { has: page.locator(iframe) }).locator('.tox-throbber')).toBeHidden({
122	    timeout: ESPERA_EDITOR,
123	  });
124	  const cuerpo = page.frameLocator(iframe).locator('body');
125	  await cuerpo.click();
126	  await cuerpo.fill(texto);
127	}
128	
129	/** Crea una pregunta desde el botón "Create a new question ..." del banco, dentro de la categoría indicada. */
130	export async function crearPregunta(page: Page, banco: number, categoria: Categoria, tipo: TipoPregunta, nombre: string) {
131	  await page.goto(urlBanco(banco, categoria));
132	  // edit.php:73 corta la página sin pintar el banco mientras la migración de mod_qbank siga en la cola de tareas ad hoc.
133	  await expect(
134	    page.getByRole('alert').filter({ hasText: 'transfer_question_categories' }),
135	    'Entorno: las tareas ad hoc de mod_qbank no terminaron; revisar el cron o ejecutarlas antes de esta prueba',
136	  ).toHaveCount(0);
137	  // Con teclado, no con click: en móvil, el punto de click de Playwright cae sobre elementos que están ANTES del botón
138	  // en el flujo (h2, filtros) o bajo la barra fija, aunque nada lo tape en el DOM. El teclado no depende de coordenadas
139	  // y recorre el mismo botón, el mismo diálogo y el mismo envío. El botón nace deshabilitado hasta que carga chooser.js
140	  // y el diálogo solo habilita "Add" al elegir un tipo: se espera cada estado porque press() no lo hace.
141	  const crear = page.getByRole('button', { name: /create a new question/i });
142	  await expect(crear).toBeEnabled();
143	  await crear.press('Enter');
144	  const tipoPregunta = page.locator(`#item_qtype_${tipo}`);
145	  await expect(tipoPregunta).toBeVisible();
146	  await tipoPregunta.press('Space');
147	  await expect(tipoPregunta).toBeChecked();
148	  const agregar = page.locator('#chooserform input.submitbutton');
149	  await expect(agregar).toBeEnabled();
150	  await agregar.press('Enter');
151	  await expect(page).toHaveURL(/question\/bank\/editquestion\/question\.php/);
152	
153	  await page.locator('#id_name').fill(nombre);
154	  await escribirEditor(page, '#id_questiontext_ifr', `Enunciado de ${nombre}`);
155	  if (tipo === 'multichoice') {
156	    await escribirEditor(page, '#id_answer_0_ifr', 'Correcta');
157	    await page.locator('#id_fraction_0').selectOption({ label: '100%' });
158	    await escribirEditor(page, '#id_answer_1_ifr', 'Incorrecta');
159	  } else if (tipo === 'truefalse') {
160	    await page.locator('#id_correctanswer').selectOption({ label: 'True' });
161	  }
162	  await page.locator('#id_submitbutton').click();
163	  await expect(page).toHaveURL(/question\/edit\.php/);
164	  await expect(filaPregunta(page, nombre)).toHaveCount(1);
165	}
166	
167	/** Add > from question bank > Switch bank > filtro de categoría > Add selected questions to the quiz. */
168	export async function agregarDesdeBanco(page: Page, examen: number, banco: number, categoria: string, preguntas: string[]) {
169	  await page.goto(`/mod/quiz/edit.php?cmid=${examen}`);
170	  await esperarModulos(page);
171	  await page.locator('.last-add-menu a[data-bs-toggle="dropdown"]').click();
172	  await page.locator('.last-add-menu [data-action="questionbank"]').click();
173	
174	  // El modal abre en el banco privado del examen; las preguntas están en el banco del curso.
175	  await page.locator('#switch-question-bank').click();
176	  // bank_switcher.js oculta esta selección justo antes de registrar el clic de los enlaces.
177	  await expect(page.locator('.search-banks .form-autocomplete-selection.d-none')).toHaveCount(1);
178	  // Tras visitarlo, el banco también aparece en "recientes" con el mismo data-newmodid; "banks in course" siempre lo lista.
179	  await page.locator(`.course-shared-banks a[data-newmodid="${banco}"]`).click();
180	
181	  // filter.js se inicia de forma asíncrona (espera cadenas de idioma) y al terminar carga la categoría por defecto, lo que
182	  // pisa un filtro aplicado antes. La primera tabla (categoría por defecto, con preguntas sembradas) marca que ya terminó.
183	  await expect(page.locator('#categoryquestions tbody tr').first()).toBeVisible({ timeout: ESPERA_EDITOR });
184	  await esperarModulos(page);
185	
