1	// Helpers compartidos por TODAS las pruebas (regresión y las generadas por la fábrica).
2	// Selectores verificados contra Moodle 5.3 en la instancia (ver ia/bitacora.md). La IA de la fábrica
3	// debe usar estos helpers en vez de reinventar selectores.
4	import { expect, type Locator, type Page } from '@playwright/test';
5	
6	export const CLAVE = 'Viaro.2026';
7	export const QUIZ_REG = 'Examen de regresión';
8	export const RECEPTOR = process.env.RECEPTOR_URL || 'http://localhost:8091';
9	
10	/**
11	 * Espera a que el JS de Moodle termine: M.util.pending_js vacío es la señal que usa Behat. Usar tras cargar una página y
12	 * tras una acción que dispara JS (filtros, autocompletar, modales) antes de la siguiente acción: Playwright es más rápido.
13	 */
14	export async function esperarJS(page: Page) {
15	  await page.waitForLoadState('load');
16	  await page.waitForFunction(() => (window as any).M?.util?.pending_js?.length === 0);
17	}
18	
19	export async function login(page: Page, usuario: string) {
20	  // Salir de la página ANTES de borrar cookies: al descargarse, Moodle lanza un POST a service.php
21	  // (core_message_get_unsent_message). Sin cookie, su respuesta fija otra MoodleSession e invalida el logintoken.
22	  await page.goto('about:blank');
23	  await page.context().clearCookies();
24	  await page.goto('/login/index.php', { waitUntil: 'domcontentloaded' });
25	  // core/togglesensitive reemplaza el input de la clave (outerHTML) al cargar y se pierde lo ya escrito:
26	  // hay que esperar a su botón antes de rellenar, o Moodle rechaza el login con la clave vacía.
27	  await expect(page.getByRole('button', { name: 'Alternar sensibilidad' })).toBeVisible();
28	  await page.fill('#username', usuario);
29	  await page.fill('#password', CLAVE);
30	  await expect(page.locator('#password')).toHaveValue(CLAVE);
31	  await page.click('#loginbtn');
32	  await expect(page.locator('#loginbtn')).toHaveCount(0);
33	}
34	
35	/** Abre la página de un quiz del curso QA101 por su nombre visible. Devuelve el cmid. */
36	export async function abrirQuiz(page: Page, nombre = QUIZ_REG): Promise<number> {
37	  await page.goto('/course/view.php?name=QA101');
38	  await page.locator('a.aalink', { hasText: nombre }).first().click();
39	  await expect(page).toHaveURL(/mod\/quiz\/view\.php\?id=\d+/);
40	  return Number(new URL(page.url()).searchParams.get('id'));
41	}
42	
43	/** Botón principal de la página del quiz (Intento de cuestionario / Continuar el último intento / Reintentar el cuestionario). */
44	export function botonIntento(page: Page): Locator {
45	  return page.getByRole('button', { name: /intento de cuestionario|continuar el último intento|reintentar el cuestionario/i });
46	}
47	
48	/** Responde una pregunta de opción múltiple o V/F por el texto de la opción, dentro del bloque de la pregunta N (1-based, número visible). */
49	export async function elegir(page: Page, pregunta: number, opcion: string) {
50	  const q = bloquePregunta(page, pregunta);
