1	// Escenario "intento con ensayo enviado, el profesor lo califica y el estudiante ve la nota final actualizada".
2	// Se usa una nota fraccionaria (0.5) para distinguir un ensayo calificado de uno ignorado o redondeado.
3	// comment.php solo funciona como ventana emergente: al guardar recarga window.opener y se cierra.
4	import { test, expect } from '@playwright/test';
5	import {
6	  abrirQuiz, bloquePregunta, botonIntento, elegir, enviarIntento, escribirEnsayo, filaResumen, login, prepararCaptura, siguientePagina,
7	} from '../../../factory/regresion/helpers';
8	import { celdasTiempoHistorial, ESPERA_EDITOR, escribirEditor, idIntento } from './soporte';
9	
10	const COMENTARIO = 'Comentario de regresión: respuesta parcial.';
11	const EDITOR_COMENTARIO = 'iframe[id$="_-comment_id_ifr"]';
12	
13	test('[CA-5] [CA-6] un profesor califica un ensayo y la nota del estudiante se actualiza', async ({ page, isMobile }) => {
14	  test.setTimeout(180_000);
15	  const numero = isMobile ? 4 : 3;
16	  const estudiante = `estudiante${numero}`;
17	
18	  await login(page, estudiante);
19	  await abrirQuiz(page);
20	  await botonIntento(page).click();
21	  await elegir(page, 1, 'One');
22	  await elegir(page, 2, 'True');
23	  await siguientePagina(page);
24	  await elegir(page, 3, 'One');
25	  await elegir(page, 4, 'True');
26	  await siguientePagina(page);
27	  await elegir(page, 5, 'True');
28	  await escribirEnsayo(page, 6, 'Una rana saltó al estanque.');
29	  await enviarIntento(page);
