31	
32	  await expect(filaResumen(page, 'Status')).toHaveText('Finished');
33	  await expect(filaResumen(page, 'Grade')).toHaveText('Not yet graded');
34	  await expect(filaResumen(page, 'Marks')).toHaveCount(0);
