  await expect(page.locator('.tox-tinymce', { has: page.locator(iframe) }).locator('.tox-throbber')).toBeHidden({
    timeout: ESPERA_EDITOR,
  });
  const cuerpo = page.frameLocator(iframe).locator('body');
  await cuerpo.click();
  await cuerpo.fill(texto);
}

