type ConfigMoodle = { courseId: number; contextid: number; sesskey: string };

const configMoodle = (page: Page): Promise<ConfigMoodle> =>
  page.evaluate(() => (window as unknown as { M: { cfg: ConfigMoodle } }).M.cfg);

